query.query:
query {
  updateComment(id: "1 OR 1=1") {
    input {
      id
      content
    }
  }
}

query NonAliasedUpdateComment {
  updateComment(id: "1") {
    input {
      id
      content
    }
  }
}

query NonAliasedUpdateComment {
  s: updateComment(id: "1") {
    s: input {
      s: id
      s: content
    }
  }
}

query Introspection {
  updateComment {
    types {
      name
      kind
    }
  }
}

query FieldSuggestions {
  updateComment(id: 1) {
    id
    field {
      name
      type
    }
  }
}

mutation BasicUpdateComment {
  updateComment(id: 1) {
    input {
      id
      content
    }
  }
}
